from dataclasses import dataclass, asdict

@dataclass
class Desenho:
    textos: tuple
    posicoes_elevadas: tuple
    largura_referencia: int
    altura_referencia: int

@dataclass
class Estado:
    arr: list
    arrText: list
    display: '_Tela'
    width_reference: int
    height_reference: int

@dataclass
class Configuracao:
    FREQUENCY_CLOCK: int

FREQUENCY_CLOCK = 3
configuracao = Configuracao(FREQUENCY_CLOCK)

class _Texto:
    """Texto ja renderizado de um elemento."""

    def __init__(self, valor):
        self.valor = valor


class _Tela:
    """Guarda os quadros em vez de desenhar."""

    def __init__(self):
        self.quadros = []


class _Relogio:
    """Guarda a taxa de cada tick em vez de esperar."""

    def __init__(self):
        self.ticks = []

    def tick(self, framerate):
        self.ticks.append(framerate)


clock = _Relogio()

def draw_array(display: '_Tela', desenho: Desenho):
    display.quadros.append(asdict(desenho))


def swap_elements(arr: list, arrText: list, i: int, j: int):
    arr[i], arr[j] = arr[j], arr[i]
    arrText[i], arrText[j] = arrText[j], arrText[i]


def compare_elements(state: Estado) -> bool:
    arr, arrText, display, width_reference, height_reference, i, j = state.arr, state.arrText, state.display, state.width_reference, state.height_reference, state.i, state.j
    draw_array(display, Desenho(asdict(arr), asdict(arrText), width_reference, height_reference))
    clock.tick(configuracao.FREQUENCY_CLOCK)
    draw_array(display, Desenho(asdict(arr), asdict(arrText), width_reference, height_reference, posicoes_elevadas=[i, j]))
    clock.tick(configuracao.FREQUENCY_CLOCK)
    if (arr[i] > arr[j] and i < j) or (arr[i] < arr[j] and i > j):
        return False
    return True


def compare_and_swap(state: Estado) -> bool:
    arr, arrText, display, width_reference, height_reference, i, j = state.arr, state.arrText, state.display, state.width_reference, state.height_reference, state.i, state.j
    swapped = False
    draw_array(display, Desenho(asdict(arr), asdict(arrText), width_reference, height_reference))
    clock.tick(configuracao.FREQUENCY_CLOCK)
    draw_array(display, Desenho(asdict(arr), asdict(arrText), width_reference, height_reference, posicoes_elevadas=[i, j]))
    clock.tick(configuracao.FREQUENCY_CLOCK)
    if (arr[i] > arr[j] and i < j) or (arr[i] < arr[j] and i > j):
        swap_elements(arr, arrText, i, j)
        draw_array(display, Desenho(asdict(arr), asdict(arrText), width_reference, height_reference, posicoes_elevadas=[i, j]))
        clock.tick(configuracao.FREQUENCY_CLOCK)
        swapped = True
    draw_array(display, Desenho(asdict(arr), asdict(arrText), width_reference, height_reference))
    clock.tick(configuracao.FREQUENCY_CLOCK)
    return swapped


def simulate_quicksort(state: Estado):
    # generated by github copilot
    def partition(arr, arrText, display, width_reference, height_reference, low, high):
        i = low - 1
        # pivot = arr[high]
        for j in range(low, high):
            if compare_elements(Estado(arr, arrText, display, width_reference, height_reference, j, high)):
                i += 1
                if i != j:
                    compare_and_swap(Estado(arr, arrText, display, width_reference, height_reference, i, j))
        if i + 1 != high:
            compare_and_swap(Estado(arr, arrText, display, width_reference, height_reference, i + 1, high))
        return i + 1

    def quicksort(arr, arrText, display, width_reference, height_reference, low, high):
        if low < high:
            pi = partition(
                arr, arrText, display, width_reference, height_reference, low, high
            )
            quicksort(
                arr, arrText, display, width_reference, height_reference, low, pi - 1
            )
            quicksort(
                arr, arrText, display, width_reference, height_reference, pi + 1, high
            )

    quicksort(
        state.arr, state.arrText, state.display, state.width_reference, state.height_reference, 0, len(state.arr) - 1
    )
    draw_array(state.display, Desenho(asdict(state.arr), asdict(state.arrText), state.width_reference, state.height_reference))
    clock.tick(configuracao.FREQUENCY_CLOCK)


def executar(valores):
    """Ordena uma copia de valores, animando cada passo. Ponto de entrada publico.

    Devolve (lista ordenada, quadros desenhados, taxas dos ticks do relogio).
    Cada quadro e (textos, posicoes destacadas, largura, altura).
    """
    arr = list(valores)
    textos = [_Texto(str(x)) for x in arr]
    tela = _Tela()
    clock.ticks.clear()
    simulate_quicksort(Estado(arr, textos, tela, 40, 100, i=0, j=0))
    return arr, tela.quadros, list(clock.ticks)
